"""Evidence-based rejection of a backdrive-loss-only cure, not causal overclaim."""
import argparse,csv,json
from pathlib import Path
import numpy as np
from analyse import BASE,sha

def spectrum(values,dt):
 x=np.asarray(values);x=x-x.mean();f=np.fft.rfftfreq(len(x),dt);power=abs(np.fft.rfft(x))**2;power[0]=0;k=int(power.argmax());return dict(dominant_sampled_frequency_Hz=float(f[k]),fraction_of_nonDC_sampled_power=float(power[k]/power.sum()) if power.sum()>0 else None,n=len(x),scope='Finite0.4s sampled diagnostic; not a calibrated mode or continuous spectrum')

def main():
 p=argparse.ArgumentParser();p.add_argument('--tag',required=True);a=p.parse_args();files=[BASE/'results'/s/'summary.json' for s in ['crimp_goal_window1915','braked_assessment1928_goal','crimp_boundary1912','braked_boundary1929']];old,new,bo,bn=[json.loads(f.read_text()) for f in files];root_old=max(r['maximum_output_port_speed_mm_s'] for r in bo['records']);root_new=max(r['maximum_output_port_speed_mm_s'] for r in bn['records']);details=[]
 for case in ['crimp_hold1904','braked_hold1925']:
  src=BASE/'results'/case;rows=list(csv.DictReader((src/'object.csv').open()));rs=[r for r in rows if 1.6-1e-12<=float(r['time_s'])<=2.+1e-12];assert len(rs)==161;v=np.array([np.fromstring(r['rigid_v'],sep=' ') for r in rs]);imp=np.array([np.fromstring(r['object_impulse_Ns_Nms'],sep=' ') for r in rs]);force=imp[:,:3]/.0025;details.append(dict(case=case,vertical_speed_spectrum=spectrum(v[:,2],.0025),vertical_contact_force_spectrum=spectrum(force[:,2],.0025),contact_force_std_N=force.std(0).tolist(),translational_velocity_RMS_mm_s=(np.sqrt((v[:,:3]**2).mean(0))*1000).tolist()));files.append(src/'object.csv')
 hypothesis_rejected=root_new<root_old and new['maximum_speed_mm_s']>=old['maximum_speed_mm_s'];d=dict(status='REJECT_BACKDRIVE_PASSIVE_LOSS_AS_SUFFICIENT_CURE' if hypothesis_rejected else 'INCONCLUSIVE_BACKDRIVE_CURE',old_root_port_max_speed_mm_s=root_old,new_root_port_max_speed_mm_s=root_new,root_port_peak_reduction_fraction=1-root_new/root_old,old_object_max_speed_mm_s=old['maximum_speed_mm_s'],new_object_max_speed_mm_s=new['maximum_speed_mm_s'],old_Skin_vertical_mean_N=old['hold_mean_skin_vertical_N'],new_Skin_vertical_mean_N=new['hold_mean_skin_vertical_N'],new_all_inputs_cap_entire_hold=all(r['input_cap_samples']==161 for r in bn['records']),details=details,source_sha256=sha(Path(__file__)),input_hashes={str(f.relative_to(BASE)):sha(f) for f in files},scope='Single-variable delayed passive-loss comparison with actual pre-engagement purity. Root motion suppressed but object speed fails more; backdrive-only sufficiency rejected, NOT proof backdrive has no contribution or FEM/contact uniquely causes failure. No coefficient/timing/force/dt scan. Need separate physically qualified holding transmission/static brake model or new contact/FEM hypothesis, not larger damping. Candidate not adopted.');out=BASE/'results'/a.tag;out.mkdir(exist_ok=False);(out/'producer.py').write_bytes(Path(__file__).read_bytes());(out/'summary.json').write_text(json.dumps(d,indent=2));print(json.dumps({k:v for k,v in d.items() if k not in ['input_hashes']},indent=2))
if __name__=='__main__':main()
